import{_ as a,f as e,c as r,a6 as d}from"./chunks/framework.CJQKpl5I.js";const s=JSON.parse('{"title":"智能体应用开发实践赛 · 知识手册","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function h(l,t,n,o,_,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="智能体应用开发实践赛-·-知识手册" tabindex="-1">智能体应用开发实践赛 · 知识手册 <a class="header-anchor" href="#智能体应用开发实践赛-·-知识手册" aria-label="Permalink to &quot;智能体应用开发实践赛 · 知识手册&quot;">​</a></h1><p>基于操作系统 AI+ 理论模拟练习备考手册，覆盖官方考核五大模块。</p><h2 id="官方考核结构" tabindex="-1">官方考核结构 <a class="header-anchor" href="#官方考核结构" aria-label="Permalink to &quot;官方考核结构&quot;">​</a></h2><p>理论考试共 60 题：单选题 30 道、多选题 10 道、判断题 20 道。初赛只考理论，省赛理论加实操。</p><table tabindex="0"><thead><tr><th>考核模块</th><th>占比</th><th>手册章节</th></tr></thead><tbody><tr><td>人工智能基础理论</td><td>30%</td><td><a href="/ch01_ai_foundation">第 1 章</a></td></tr><tr><td>国产操作系统技术基础</td><td>20%</td><td><a href="/ch02_os_linux">第 2 章</a></td></tr><tr><td>国产软件技术基础</td><td>20%</td><td><a href="/ch03_software">第 3 章</a></td></tr><tr><td>智能体技术基础</td><td>20%</td><td><a href="/ch04_agent">第 4 章</a></td></tr><tr><td>国产硬件技术基础</td><td>10%</td><td><a href="/ch05_hardware">第 5 章</a></td></tr></tbody></table><h2 id="章节导览" tabindex="-1">章节导览 <a class="header-anchor" href="#章节导览" aria-label="Permalink to &quot;章节导览&quot;">​</a></h2><ul><li><a href="/ch01_ai_foundation">第 1 章 人工智能基础理论</a> 机器学习范式与优化主线、LLM 原理、推理采样、模型工程、向量检索（RAG 基础）</li><li><a href="/ch02_os_linux">第 2 章 国产操作系统技术基础</a> 内核与启动流程、Shell 与命令、文件权限、进程服务、存储、网络、包管理与生态适配</li><li><a href="/ch03_software">第 3 章 国产软件技术基础</a> 数据库与数据文件、中间件、容器与分布式、兼容迁移、国产软件生态</li><li><a href="/ch04_agent">第 4 章 智能体技术基础</a> Agent 架构闭环、工具调用、RAG、MCP、Skill、安全评测</li><li><a href="/ch05_hardware">第 5 章 国产硬件技术基础</a> 国产 CPU 与指令集、兼容层次、异构计算、GPU 与 CUDA、国产生态、训练集群与液冷</li><li><a href="/ch06_appendix">第 6 章 附录</a> 高频考点、判断题陷阱、易混对照、命令速查、排障速查</li><li><a href="/ch07_mcp_agent_practice">第 7 章 MCP 与 Agent 落地实践</a> 可运行的 MCP 服务与 Agent 代码</li><li><a href="/graph">知识网络图</a> 全部知识点的关系图谱，点击跳转对应章节</li></ul><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><ul><li>选中正文文本可高亮标记，刷新后保留，点击高亮可删除，右上角可清除本页高亮</li><li>知识网络图按模块着色，点击节点查看详情并跳转对应知识点</li><li>右上角可切换深色模式</li></ul>',9)])])}const u=a(i,[["render",h]]);export{s as __pageData,u as default};
